program QuickSort;
{$APPTYPE CONSOLE}
uses
  System.SysUtils;
type
  TSort = class
  public
    class procedure Sort(var A: TArray<Integer>; Lo, Hi: Integer); static;
  end;

class procedure TSort.Sort(var A: TArray<Integer>; Lo, Hi: Integer);
var
  I, J, Pivot, T: Integer;
begin
  if Lo >= Hi then
    Exit;
  Pivot := A[Hi];
  I := Lo;
  for J := Lo to Hi - 1 do
    if A[J] <= Pivot then
    begin
      T := A[I];
      A[I] := A[J];
      A[J] := T;
      Inc(I);
    end;
  T := A[I];
  A[I] := A[Hi];
  A[Hi] := T;
  Sort(A, Lo, I - 1);
  Sort(A, I + 1, Hi);
end;

var
  A: TArray<Integer>;
  I: Integer;
begin
  A := [29, 3, 72, 15, 8, 41, 3, 56];
  TSort.Sort(A, 0, High(A));
  for I := 0 to High(A) do
  begin
    if I > 0 then
      Write(' ');
    Write(A[I]);
  end;
  Writeln;
end.

program Validate;
{$APPTYPE CONSOLE}
uses
  System.SysUtils;
type
  EValidationError = class(Exception);
  ERangeError2 = class(EValidationError);

procedure ValidateScore(S: Integer);
begin
  if S < 0 then
    raise EValidationError.CreateFmt('%d is negative', [S]);
  if S > 100 then
    raise ERangeError2.CreateFmt('%d is above 100', [S]);
end;

const
  Scores: array[0..2] of Integer = (-5, 50, 150);
var
  Count: Integer;
begin
  Count := 0;
  try
    for var S in Scores do
    begin
      Inc(Count);
      try
        ValidateScore(S);
        Writeln('ok ', S);
      except
        on E: ERangeError2 do
          Writeln('range: ', E.Message);
        on E: EValidationError do
          Writeln('invalid: ', E.Message);
      end;
    end;
  finally
    Writeln('checked ', Count);
  end;
end.

program Factors;
{$APPTYPE CONSOLE}
uses
  System.SysUtils;

function Factorise(N: Integer): string;
var
  P, E: Integer;
begin
  Result := '';
  P := 2;
  while N > 1 do
  begin
    E := 0;
    while N mod P = 0 do
    begin
      N := N div P;
      Inc(E);
    end;
    if E > 0 then
    begin
      if Result <> '' then
        Result := Result + ' * ';
      Result := Result + IntToStr(P);
      if E > 1 then
        Result := Result + '^' + IntToStr(E);
    end;
    Inc(P);
  end;
end;

const
  Numbers: array[0..3] of Integer = (360, 97, 1001, 1024);
begin
  for var N in Numbers do
    Writeln(N, ' = ', Factorise(N));
end.

