end;

function TMatrix2.Power(N: Integer): TMatrix2;
var
  Base: TMatrix2;
begin
  Result := Make(1, 0, 0, 1);
  Base := Self;
  while N > 0 do
  begin
    if Odd(N) then
      Result := Result.Mul(Base);
    Base := Base.Mul(Base);
    N := N div 2;
  end;
end;

